// ai-setup policy guard for OpenCode 2: every bash permission goes through core/guard/guard.py, the same
// logic Claude Code's hook uses. Generated by install.py ({{AI_SETUP}} is replaced): edit it in ai-setup.
// The V2 plugin API is beta: setup never throws, so a changed API silently means "no guard".
// After updating OpenCode, check it still asks: `git push` in a session must prompt.
import { spawnSync } from "node:child_process"

const GUARD = "{{AI_SETUP}}/core/guard/guard.py"

function check(command) {
  const run = spawnSync("python3", ["-I", GUARD], {
    input: JSON.stringify({ tool: "bash", command }),
    encoding: "utf8",
    timeout: 10000,
  })
  try {
    return JSON.parse(run.stdout)
  } catch {
    return { decision: "ask", reason: "policy guard failed; confirm manually" } // a broken guard must not allow
  }
}

export default {
  id: "ai-setup-guard",
  async setup(ctx) {
    if (typeof ctx?.permission?.hook !== "function") return async () => {}
    await ctx.permission.hook("evaluate", (event) => {
      if (event.action !== "bash") return
      const { decision, reason } = check((event.resources || []).join(" "))
      if (decision === "ask" || decision === "deny") {
        event.effect = decision
        event.message = reason
      }
    })
  },
}
